import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaFilter, FaPlus } from 'react-icons/fa';
import { useAuth } from '../../context/AuthContext';
import { useLanguage } from '../../context/LanguageContext';
import { useTheme } from '../../context/ThemeContext';
import { useFilters } from '../../hooks/useFilters';
import Button from '../../components/common/Button/Button';
import AdvertCard from '../../components/AdvertCard/AdvertCard';
import FilterSection from '../../components/FilterSection/FilterSection';
import advertService from '../../services/advertService';
import styles from './HomePage.module.css';

const HomePage = () => {
    const navigate = useNavigate();
    const { user, isAuthenticated } = useAuth();
    const { t } = useLanguage();
    const { theme } = useTheme();
    const { filters, showFilters, setShowFilters, applyFilters } = useFilters();

    const [activeTab, setActiveTab] = useState('all');
    const [adverts, setAdverts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const loadAdverts = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            let response;
            switch (activeTab) {
                case 'my':
                    if (!isAuthenticated) { setAdverts([]); setLoading(false); return; }
                    response = await advertService.getMyAdverts();
                    break;
                case 'participating':
                    if (!isAuthenticated) { setAdverts([]); setLoading(false); return; }
                    response = await advertService.getParticipatingAdverts();
                    break;
                default:
                    response = await advertService.getAllAdverts(filters);
            }
            const advertsData = response.adverts || [];
            console.log('Loaded adverts with isParticipating:', advertsData.map(a => ({ id: a.id, isParticipating: a.isParticipating })));
            setAdverts(advertsData);
        } catch (err) {
            setError(err.message || t('loadingError'));
        } finally {
            setLoading(false);
        }
    }, [activeTab, filters, isAuthenticated, t]);

    useEffect(() => { loadAdverts(); }, [loadAdverts]);

    const handleSubscribe = async (advertId, currentParticipatingStatus) => {
        if (!isAuthenticated) { navigate('/login'); return; }
        try {
            if (currentParticipatingStatus) {
                await advertService.unsubscribeFromAdvert(advertId);
            } else {
                await advertService.subscribeToAdvert(advertId);
            }

            // Обновляем состояние локально без перезагрузки всех объявлений
            setAdverts(prevAdverts =>
                prevAdverts.map(advert => {
                    if (advert.id === advertId) {
                        const newStatus = !currentParticipatingStatus;
                        const newCount = currentParticipatingStatus
                            ? (advert.participantsCount || 1) - 1
                            : (advert.participantsCount || 0) + 1;
                        return {
                            ...advert,
                            isParticipating: newStatus,
                            participantsCount: newCount
                        };
                    }
                    return advert;
                })
            );
        } catch (err) {
            alert(err.message);
        }
    };

    const handleDelete = async (advertId) => {
        if (window.confirm(t('confirmDelete'))) {
            try {
                await advertService.deleteAdvert(advertId);
                await loadAdverts();
            } catch (err) {
                alert(err.message);
            }
        }
    };

    const handleEdit = (advertId) => navigate(`/add-advert?edit=${advertId}`);
    const handleApplyFilters = (newFilters) => applyFilters(newFilters);

    const tabs = [
        { id: 'all', label: t('allAdverts') },
        { id: 'my', label: t('myAdverts') },
        { id: 'participating', label: t('participating') }
    ];

    return (
        <div className={styles.homePage}>
            <div className={styles.hero}>
                <div className={styles.heroContent}>
                    <h1 className={styles.heroTitle}>{t('findTeam')}</h1>
                    <p className={styles.heroSubtitle}>{t('joinGames')}</p>
                    {isAuthenticated ? (
                        <Button size="large" icon={FaPlus} onClick={() => navigate('/add-advert')}>{t('createAdvert')}</Button>
                    ) : (
                        <Button size="large" onClick={() => navigate('/login')}>{t('login')}</Button>
                    )}
                </div>
            </div>

            <div className={styles.tabsSection}>
                <div className={styles.container}>
                    <div className={styles.tabsHeader}>
                        <div className={styles.tabs}>
                            {tabs.map(tab => (
                                <button
                                    key={tab.id}
                                    className={`${styles.tab} ${activeTab === tab.id ? styles.activeTab : ''}`}
                                    onClick={() => setActiveTab(tab.id)}
                                >
                                    {tab.label}
                                </button>
                            ))}
                        </div>
                        <Button variant="outline" size="small" icon={FaFilter} onClick={() => setShowFilters(!showFilters)}>
                            {t('filters')}
                        </Button>
                    </div>

                    {showFilters && <FilterSection onApplyFilters={handleApplyFilters} initialFilters={filters} />}

                    {loading ? (
                        <div className={styles.loadingState}>
                            <div className={styles.spinner} />
                            <p>{t('loading')}</p>
                        </div>
                    ) : error ? (
                        <div className={styles.errorState}>
                            <p>{error}</p>
                            <Button onClick={loadAdverts}>{t('tryAgain')}</Button>
                        </div>
                    ) : adverts.length === 0 ? (
                        <div className={styles.emptyState}>
                            <p className={styles.emptyMessage}>{t('noAdverts')}</p>
                            {isAuthenticated && activeTab === 'all' && (
                                <Button onClick={() => navigate('/add-advert')}>{t('createFirst')}</Button>
                            )}
                        </div>
                    ) : (
                        <div className={styles.advertsGrid}>
                            {adverts.map((advert) => {
                                const isCreator = user && advert.userId === user.id;
                                const isParticipating = advert.isParticipating === true;

                                return (
                                    <AdvertCard
                                        key={advert.id}
                                        advert={advert}
                                        isCreator={isCreator}
                                        isParticipating={isParticipating}
                                        onSubscribe={() => handleSubscribe(advert.id, isParticipating)}
                                        onEdit={() => handleEdit(advert.id)}
                                        onDelete={() => handleDelete(advert.id)}
                                        onClick={() => navigate(`/advert/${advert.id}`)}
                                    />
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default HomePage;
